  raw = raw.replace(/\r\n/g, '\n');
  const nl = raw.indexOf('\n\n');
  hdr = parseHeaders(nl < 0 ? raw : raw.slice(0, nl));
  const acc = { text: '', html: '', adjuntos: [], correos_anidados: 0 };
