      tamano: a.size != null ? a.size : (buf ? buf.length : null),
      sha256: (a.sha256 || sha('sha256', buf) || null), md5: (a.md5 || sha('md5', buf) || null),
      content_id: null, inline: false, url_media: a.url || null
    });
  }
