messageId = src.messageId || src.message_id || h1('message-id');

function parseAddr(s) {
  s = String(s || '').trim();
  const m = /<([^>]+)>/.exec(s);
  const addr = (m ? m[1] : (/[\w.+-]+@[\w.-]+/.exec(s) || [''])[0]).trim().toLowerCase();
