    let data = res.body;
    if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { /* respuesta de texto */ } }
    return { ok: res.statusCode >= 200 && res.statusCode < 300, status: res.statusCode, data };
  } catch (e) {
    return { ok: false, status: 0, error: String((e && e.message) || e) };
  }
}

