function registrable(host) {
  const p = String(host || '').toLowerCase().replace(/\.$/, '').split('.').filter(Boolean);
  if (p.length <= 2) return p.join('.');
  const last2 = p.slice(-2).join('.');
  if (SLD2.has(last2) && p.length >= 3) return p.slice(-3).join('.');
