  const p = String(ip).split('.').map(Number);
  if (p.length !== 4 || p.some(n => isNaN(n) || n > 255)) return true;
  return p[0] === 10 || p[0] === 127 || p[0] === 0 || p[0] >= 224 ||
    (p[0] === 172 && p[1] >= 16 && p[1] <= 31) || (p[0] === 192 && p[1] === 168) ||
